/**
 * Calculate subtotal, discount, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discount percent if provided
  const discount = discountPercent ?? 0;
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with this SKU
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Increase qty on existing line
    newLines[existingLineIndex].qty += qty;
  } else {
    // Add new line at the end
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  const newInvoice = { ...invoice, lines: newLines };
  return ok(newInvoice);
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line with this SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without this line
  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  const newInvoice = { ...invoice, lines: newLines };
  return ok(newInvoice);
}

/**
 * Issue an invoice (assign a number and change status to 'issued').
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Create new invoice with number and issued status
  const newInvoice = { ...invoice, number, status: 'issued' };
  return ok(newInvoice);
}

/**
 * Check if a string is a valid date in YYYY-MM-DD format and represents a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  // Check format is YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;

  // Check it's a real date
  const date = new Date(dateStr + 'T00:00:00Z');
  const dateOnly = dateStr.split('-');
  const year = parseInt(dateOnly[0], 10);
  const month = parseInt(dateOnly[1], 10);
  const day = parseInt(dateOnly[2], 10);

  // Verify the date components match (to catch invalid dates like 2024-02-30)
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return false;
  }

  return true;
}

