test('createInvoice applies tier discount for lines without explicit discount', () => {
  // C-001 is gold tier (5% discount)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies different tier discounts for different customers', () => {
  // C-001 is gold (5), C-002 is standard (0), C-003 is silver (2.5)
  const goldResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const standardResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const silverResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(goldResult.ok, true);
  assert.equal(goldResult.value.lines[0].discountPercent, 5);

  assert.equal(standardResult.ok, true);
  assert.equal(standardResult.value.lines[0].discountPercent, 0);

  assert.equal(silverResult.ok, true);
  assert.equal(silverResult.value.lines[0].discountPercent, 2.5);
});

test('createInvoice respects explicit discountPercent even if it is 0', () => {
  // C-001 is gold tier (5% discount) but line has explicit 0%
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice respects explicit discountPercent over tier discount', () => {
  // C-001 is gold tier (5%) but line has explicit 15%
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 15 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 15);
});

test('createInvoice with mixed lines (some explicit, some tier)', () => {
  // C-003 is silver tier (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // No explicit discount, uses tier 2.5%
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 }, // Explicit 10%
      { sku: 'COPY-HOUR', qty: 1, discountPercent: 0 }, // Explicit 0%, overrides tier
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 10);
  assert.equal(result.value.lines[2].discountPercent, 0);
});

test('createInvoice calculates totals with tier discounts', () => {
  // C-001 is gold (5%)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // DEV-HOUR is 9500 cents, qty 10 = 95000
  // Discount 5% = 4750
  // Total = 90250
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
