    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 1000, // 1000 cents = €10
        vatRate: 21,
        discountPercent: 150, // Invalid but we manually create for testing clamping
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // subtotal = 1000
  // discount = 1000 * 150 / 100 = 1500
  // total = max(0, 1000 - 1500) = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.total, 0);
});

